from pathlib import Path
from html import escape,unescape
import json,re,shutil
P=Path(__file__).resolve().parent;ROOT=P.parents[2];OUT=ROOT/'outputs/nanda-demo-v5';OUT.mkdir(parents=True,exist_ok=True)
prompts={p['id']:p for p in json.loads((P/'prompts.json').read_text())['prompts']}
old=(ROOT/'work/nanda-messagebox-skill/demo/index.html').read_text();css=re.search(r'<style>(.*?)</style>',old,re.S).group(1)
(OUT/'fonts').mkdir(exist_ok=True);shutil.copy2(P/'production/player/assets/inter-latin.woff2',OUT/'fonts/inter-latin.woff2');shutil.copy2(P/'production/player/assets/OFL.txt',OUT/'fonts/OFL.txt')
def prompt(pid,label=None):
 p=prompts[pid];return f'<div class="prompt-card"><p class="prompt" id="p-{pid}" data-prompt="{pid}">{escape(p["text"])}</p><div class="prompt-footer"><span>{escape(label or p["app"])}</span><button class="copy" data-copy="p-{pid}" type="button">Copy</button></div></div>'
def shot(id,caption):return f'<figure><a class="shot" href="screenshots/{id}.jpg" target="_blank" rel="noopener"><img src="screenshots/{id}.jpg" width="1920" height="1080" alt="{escape(caption)}" loading="lazy"></a><figcaption>{escape(caption)}. Frame from this video. Click to enlarge.</figcaption></figure>'
def step(n,title,desc,body):return f'<section class="step" id="step-{n}"><div class="step-copy"><div class="step-heading"><span class="step-number">{n}</span><h3>{title}</h3></div><p>{desc}</p></div>{body}</section>'
body=step(1,'Set up both agents','Alice uses Muse. Bob uses Wajo. Each person uses their own email.',prompt('setup_alice')+shot('connect_alice','Alice sets up her bakery agent in Muse')+prompt('setup_bob')+shot('connect_bob','Bob sets up his agent in Wajo'))
body+=step(2,'Verify your email','Use the code from your own inbox. It proves control of your email account.',prompt('verify')+shot('verify','Enter your own verification code'))
body+=step(3,'Contact a business you know','Bob already knows bakery.com. In this example, the bakery publishes its agent contact details on its website, so Bob can use that direct path.',prompt('ask')+shot('known','Bob asks the known bakery about cakes')+prompt('check_alice')+prompt('menu_reply')+prompt('check_bob')+shot('menu','Alice replies and Bob receives the menu'))
body+=step(4,'Let the business contact you later','After an order, Bob allows updates. Alice starts a new message using Bob’s registered ID.',prompt('update')+shot('later','Alice starts a new message to Bob')+'<p>The Index resolves Bob’s ID to his hosted Agent Card. The card supplies the current endpoint and access rules. Bob can register his email without owning a website.</p>'+shot('resolve','The Index resolves one known ID to its hosted card')+'<p>Alice’s agent checks permissions, then AgentBox delivers the update. Bob uses the same “Check my AgentBox.” prompt to read it.</p>'+shot('deliver','Bob receives the bakery update'))
body+=step(5,'Reply from your own app','Bob replies in Wajo. Alice checks her AgentBox in Muse.',prompt('reply')+'<p>Alice uses the same “Check my AgentBox.” prompt to read Bob’s reply.</p>'+shot('reply','Bob replies to Alice'))
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="An illustrated bakery demo of known agent ID resolution and messages between Muse and Wajo."><title>Known agent ID demo | NANDA Index</title><style>{css}</style></head><body>
<a class="skip" href="#prompts">Skip to the steps</a><header class="site-header"><nav class="guide resource-links" aria-label="NANDA resources"><a class="resource-button primary" href="https://my.nandaindex.org/">SKILL.MD</a><a class="resource-button" href="https://nandaindex.org/">NANDA Index</a><a class="resource-button" href="https://agentboxnanda.org/">AgentBox</a></nav></header>
<main class="guide"><section class="intro"><div class="eyebrow">Animated bakery walkthrough</div><h1>Connect agents using a known ID</h1><p class="lead">Alice uses Muse. Bob uses Wajo. Their agents exchange messages, including when the bakery contacts Bob later.</p></section>
<figure class="player"><div class="player-frame"><video controls preload="metadata" playsinline poster="video/muse-wajo-demo-v5-poster.jpg"><source src="video/muse-wajo-demo-v5.mp4" type="video/mp4"><track kind="captions" src="video/muse-wajo-demo-v5.vtt" srclang="en" label="English"><a href="video/muse-wajo-demo-v5.mp4">Download the video</a></video></div><figcaption>2:28. Screens and addresses are illustrative. The prompts below match the video.</figcaption></figure>
<section class="roles-section"><div class="roles"><article class="role"><h3>The Index resolves an ID</h3><p>A known ID leads to its hosted Agent Card, which provides current contact details.</p></article><article class="role delivery"><h3>AgentBox carries messages</h3><p>Agents send and receive messages while following the recipient’s permissions.</p></article></div></section>
<div id="prompts" class="section-title"><h2>Follow the walkthrough</h2></div><p>Examples are fictional. Replace the emails, code and domain with your own before using a prompt.</p>{body}
<section class="closing"><h2>Keep your own agent app</h2><p>The Index provides neutral identity resolution across agent systems. A resolved ID gives the contact path; permission governs the connection.</p><a class="button" href="https://my.nandaindex.org/">Open SKILL.MD</a></section>
<div class="sources"><p>Architecture: <a href="https://datatracker.ietf.org/doc/html/draft-raskar-agentic-web-federated-resolution-01">Known identity resolution draft</a>. The domain’s published contact path is assumed in this illustration.</p><p><a href="../">Original demos and guide</a> | <a href="bakery-demo-script-v5-google.docx">Download the review script</a></p></div></main>
<script>document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{{const text=document.getElementById(button.dataset.copy).textContent;try{{await navigator.clipboard.writeText(text);button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1600)}}catch(e){{const range=document.createRange();range.selectNodeContents(document.getElementById(button.dataset.copy));getSelection().removeAllRanges();getSelection().addRange(range);button.textContent='Select and copy';}}}}));</script></body></html>'''
(OUT/'index.html').write_text(html)
# Assert equality against the canonical source, including all prompts and no extra input.
found={k:unescape(v) for k,v in re.findall(r'data-prompt="([^"]+)">(.*?)</p>',html)};assert found=={k:v['text'] for k,v in prompts.items()}
assert not re.search(r'\b(search|discover|discovery|discoverable)\b',re.sub(r'<[^>]+>','',html),re.I)
(OUT/'prompts.json').write_text((P/'prompts.json').read_text());print('Guide written; all nine canonical prompts match.')
